#nullable enable // autogenerated

using MVZ2.GameContent.Areas;
using PVZEngine.Level;
using PVZEngine.Tools.Random;

namespace MVZ2.GameContent.Stages
{
    public class PrimalForceBehaviour : StageBehaviour
    {
        public PrimalForceBehaviour(StageDefinition stageDef) : base(stageDef)
        {
        }
        public override void PostWave(LevelEngine level, int wave)
        {
            base.PostWave(level, wave);
            var rng = level.GetSpawnRNG();
            DropGiantStones(level, STONE_COUNT, rng);
        }
        public static void DropGiantStones(LevelEngine level, int count, RandomGenerator rng)
        {
            Mountain.DropGiantStones(level, COLUMN_MIN, COLUMN_MAX, 0, level.GetMaxLaneCount() - 1, count, rng);
        }
        public const int COLUMN_MIN = 3;
        public const int COLUMN_MAX = 6;
        public const int STONE_COUNT = 3;
    }
}
